INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('8c2ff870-c484-4716-b31b-cf4d3ed019e5', '051b209e-9985-44da-a832-ca884783cb98', 4, 'O Silêncio Educativo', NULL, '{"intro": "Falar demais \u00e9 uma fuga do encontro consigo mesmo.", "prayer": "No sil\u00eancio, escute os batimentos do seu cora\u00e7\u00e3o.", "practice": "Fique 30 minutos sem falar nada, apenas observando.", "reflection": "Quem n\u00e3o domina a pr\u00f3pria l\u00edngua n\u00e3o domina a si mesmo.", "journal_prompt": "O que o seu barulho tenta esconder?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;